import React, { useState, useEffect } from 'react';
import StatusStepper from '../components/StatusStepper';
import PackingList from '../components/PackingList';
import { UserIcon, MapPinIcon, PhoneIcon, TruckIcon, ArrowPathIcon } from '@heroicons/react/24/outline';

const Orders = () => {
  // Backend එක නැති නිසා අපි මෙතනට කෙලින්ම Data දානවා
  const [order, setOrder] = useState({
    orderID: "ORD-2024-001",
    status: "Pending",
    paymentType: "Cash on Delivery",
    totalAmount: 4500.00,
    items: [
      { name: "Keells Sugar 1kg", quantity: 2, unitPriceAtSale: 250, isPacked: false },
      { name: "Anchor Milk Powder 400g", quantity: 1, unitPriceAtSale: 1100, isPacked: false },
      { name: "Munchee Super Cream Cracker", quantity: 3, unitPriceAtSale: 180, isPacked: false }
    ],
    customer: {
      name: "Saman Kumara",
      phoneNumber: "0712345678",
      address: {
        houseNumber: "No. 45",
        street: "Temple Road, Maharagama",
        landMark: "Near the Clock Tower"
      }
    }
  });

  const [drivers] = useState([
    { _id: "1", name: "Sunil Perera", vehicleType: "Bike" },
    { _id: "2", name: "Kamal Silva", vehicleType: "Three-Wheel" }
  ]);
  
  const [selectedDriverId, setSelectedDriverId] = useState('');
  const [loading, setLoading] = useState(false);

  const advanceStatus = () => {
    const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
    const currentIdx = statuses.indexOf(order.status);
    const nextStatus = statuses[currentIdx + 1];

    if (currentIdx < statuses.length - 1) {
      if (nextStatus === 'Out for Delivery' && !selectedDriverId) {
        alert("Please assign a driver before sending the order out!");
        return;
      }
      // Backend එකක් නැති නිසා අපි state එක විතරක් update කරනවා
      setOrder({ ...order, status: nextStatus });
    }
  };

  const toggleItemPacked = (index) => {
    const newItems = [...order.items];
    newItems[index].isPacked = !newItems[index].isPacked;
    setOrder({ ...order, items: newItems });
  };

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <aside className="w-64 bg-gradient-to-b from-blue-700 to-blue-900 text-white flex flex-col shadow-xl">
        <div className="p-6 text-2xl font-black tracking-wider border-b border-blue-800">
          ONAKO <span className="text-yellow-400">BIGMART</span>
        </div>
        <nav className="mt-6 flex-1">
          <div className="bg-blue-600 border-r-4 border-yellow-400 px-6 py-3 flex items-center space-x-3 cursor-pointer">
            <TruckIcon className="w-5 h-5 text-yellow-400" />
            <span className="font-bold">Active Orders</span>
          </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-8">
        <header className="mb-8 flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Delivery Console</h1>
            <p className="text-gray-500">Local Neighborhood Management System</p>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <h2 className="text-2xl font-black text-blue-900">{order.orderID}</h2>
                  <p className="text-sm font-medium text-gray-500">
                    {order.paymentType} • <span className="text-green-600 font-bold">Rs. {order.totalAmount.toFixed(2)}</span>
                  </p>
                </div>
                <span className="px-4 py-1 rounded-full bg-blue-100 text-blue-700 text-xs font-black uppercase">
                  {order.status}
                </span>
              </div>
              <StatusStepper currentStatus={order.status} onAdvance={advanceStatus} />
            </div>
            <PackingList items={order.items} onTogglePack={toggleItemPacked} />
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
             <h3 className="font-bold text-gray-900 mb-4 flex items-center">
               <MapPinIcon className="w-5 h-5 mr-2 text-blue-600" /> Destination
             </h3>
             <p className="font-bold">{order.customer.name}</p>
             <p className="text-sm text-gray-600">{order.customer.phoneNumber}</p>
             <div className="mt-4 p-3 bg-gray-50 rounded border-dashed border-2">
               <p className="text-sm">{order.customer.address.houseNumber}, {order.customer.address.street}</p>
               <p className="text-xs text-blue-600 font-bold">Landmark: {order.customer.address.landMark}</p>
             </div>

             {(order.status === "Packing" || order.status === "Out for Delivery") && (
                <div className="mt-6 pt-4 border-t">
                  <label className="text-xs font-bold text-gray-400 uppercase">Assign Driver</label>
                  <select 
                    className="w-full mt-2 p-2 bg-gray-50 border rounded"
                    value={selectedDriverId}
                    onChange={(e) => setSelectedDriverId(e.target.value)}
                  >
                    <option value="">Select Driver</option>
                    {drivers.map(d => <option key={d._id} value={d._id}>{d.name}</option>)}
                  </select>
                </div>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default Orders;
